using s::J;using s::D;using s::need;
J checks=J::array(),proofs=J::array();
void check(bool ok,const std::string&name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);}
template<class F>void reject(F fn,const std::string&name){bool caught=false;try{fn();}catch(const std::exception&){caught=true;}check(caught,name);}
J read(const std::string&p){std::ifstream f(p);J j;f>>j;return j;}
void write(const std::string&p,const J&j){std::ofstream f(p);f<<j.dump(2)<<'\n';need(bool(f),"evidence write");}
s::Config config(bool nonuniform=false){s::Config c;c.x=nonuniform?std::vector<double>{.002,.003,.005,.007}:std::vector<double>{.002,.0045,.007};c.y={.007,.0071,.0072};c.zlo=0;c.zhi=.025;c.fixed_support=c.conditional_congruent_neutral=c.permit_native_genesis_fixture=true;c.max_fraction_loss=.01;c.max_fraction_gain=.01;c.mesh_sha256=s::hash(J({c.x,c.y,c.zlo,c.zhi}).dump());c.initial_common_sha256=s::hash("initial-common-component");c.patches={{"bottom",s::Face::Bottom,.002,.007,0,.025},{"top",s::Face::Top,.002,.007,0,.025},{"left",s::Face::Left,.007,.0072,0,.025},{"right",s::Face::Right,.007,.0072,0,.025}};return c;}
std::vector<double> temps(bool nonuniform=false){return nonuniform?std::vector<double>{1850,2100,2300,2400,2600,2800}:std::vector<double>{1850,2100,2500,2800};}
m::GapPicOptions options(){m::GapPicOptions o;o.nx=o.ny=45;o.width_m=o.gap_m=.009;o.depth_m=.025;o.finite_foils=o.finite_axial_extent=true;o.short_z_m=0;o.feed_z_m=.025;o.lower_foil={.002,.007,.0018,.002};o.upper_foil={.002,.007,.007,.0072};return o;}
std::vector<m::ArenaStateSpec> states(const s::Owner&o){return {{"SS304_CONGRUENT_NEUTRAL",0,0,0,o.atom_mass(),0,o.reference_per_atom()}};}
s::Step step(const s::Owner&o,double dt=1e-6){s::Step e;auto&b=e.binding;b.accepted_step=o.snapshot()->accepted_step;b.begin_s=o.snapshot()->time_s;b.dt_s=dt;b.end_s=b.begin_s+dt;b.material_prefix=o.prefix();b.common_sha256=s::hash("common/"+std::to_string(b.accepted_step));b.field_sha256=s::hash("field-stage");b.mesh_sha256=config().mesh_sha256;b.gas_base_sha256=s::hash("no-gas-mutation-component");b.gas_trial_sha256=s::hash("bounded-fixture/"+std::to_string(b.accepted_step));b.source_sha256=s::hash("source-owner-fixture");b.native_source_sha256=m::PicArena::source_identity();return e;}
struct Port:s::GasPort {J batch;const J&certified_batch(const s::Binding&b)const override{need(batch.at("binding")==s::Owner::describe_binding(b),"port binding");return batch;}};
Port empty_port(const s::Owner&o,const s::Step&e){Port p;p.batch={{"binding",s::Owner::describe_binding(e.binding)},{"material_sha256",s::material_seal},{"scope","v6.2-native-genesis-source-and-first-hit-fixture"},{"packets",J::array()}};(void)o;return p;}
struct NativeCase {
 m::GapPic pic{options()};std::unique_ptr<m::PicArena> arena;J sources=J::array();std::map<std::string,std::string>patches;
 NativeCase(const s::Owner&o){
  std::vector<m::GapParticle> particles;std::vector<m::ArenaPacket> packets;
  auto append=[&](const std::string&id,m::ArenaCount count,std::array<double,3>x,std::array<double,3>u,const std::string&patch){m::ArenaPacket p{id,"SS304_CONGRUENT_NEUTRAL","explicit_native_genesis_fixture","",count,{}};for(double w:m::PicArena::positive_carriers(count)){m::GapParticle q;q.mass_kg=o.atom_mass();q.charge_C=0;q.weight=w;q.position_m=x;q.proper_velocity_m_s=u;particles.push_back(q);}packets.push_back(p);patches[id]=patch;};
  // Actual locally sampled native poses at both x halves of both foil faces.
  // Only source creation is a genesis fixture: v6.2 has no typed source birth.
  for(std::string face:{"bottom","top"})for(double along:{.25,.75}){auto proposal=o.sample(face,{.21,.37,.29,along,.5});auto x=proposal.at("position_m").get<m::PicVector>(),u=proposal.at("proper_velocity_m_s").get<m::PicVector>();double dir=face=="top"?1.:-1.;x[1]=std::nextafter(x[1],dir>0?INFINITY:-INFINITY);std::string id="emit/"+face+"/"+std::to_string(along);append(id,{1e16,-.125},x,u,face);proposal["packet_id"]=id;proposal["position_m"]=x;sources.push_back(proposal);
   // Incoming pre-existing gas hits the SAME spatial cells during native drift.
   // Kinematics are real native first-hit receipts, not prescribed wall heat.
   auto incoming=x;incoming[1]+=dir*1e-7;std::array<double,3>v{0,-dir*500,0};append("collect/"+face+"/"+std::to_string(along),{1e14,-.0009765625},incoming,v,face);
  }
  auto ids=pic.add_authored_batch(particles);std::size_t at=0;for(auto&p:packets)for(std::size_t k=0;k<m::PicArena::positive_carriers(p.count).size();++k)p.native_ids.push_back(ids.at(at++));pic.solve_fields();arena=std::make_unique<m::PicArena>(pic,states(o),std::vector<m::ArenaChannel>{},packets,"spatial-material/native-genesis-fixture");
 }
};
J packet_base(const s::Owner&o,const std::string&id,const std::string&patch,bool emit,const m::PicVector&x,const m::PicVector&u,double time){return {{"receipt_id",id},{"packet_id",id},{"patch",patch},{"emit",emit},{"species","SS304_CONGRUENT_NEUTRAL"},{"mass_per_atom_kg",o.atom_mass()},{"internal_per_atom_J",0},{"reference_per_atom_J",o.reference_per_atom()},{"full_packet",true},{"native_removed",!emit},{"first_hit",!emit},{"position_m",x},{"proper_velocity_m_s",u},{"time_s",time},{"carriers",J::array()}};}
struct NativePort:s::GasPort {
 NativeCase& fixture;m::PreparedArena&trial;J batch;
 NativePort(const s::Owner&o,NativeCase&c,m::PreparedArena&t,const s::Step&e,bool source):fixture(c),trial(t){
  const auto&a=t.audit();need(c.arena->can_publish(t)&&e.binding.gas_trial_sha256==s::hash(a.dump())&&e.binding.gas_base_sha256==c.arena->state_prefix()&&a.at("start_time_s")==e.binding.begin_s&&a.at("dt_s")==e.binding.dt_s,"actual v6.2 staged native binding");batch={{"binding",s::Owner::describe_binding(e.binding)},{"material_sha256",s::material_seal},{"scope","v6.2-native-genesis-source-and-first-hit-fixture"},{"raw_native_audit",a},{"packets",J::array()}};
  if(source)for(auto&proposal:c.sources){std::string id=proposal.at("packet_id");auto pose=c.arena->view(id);need(proposal.at("position_m")==J(pose.position_m)&&proposal.at("proper_velocity_m_s")==J(pose.proper_velocity_m_s),"actual native source pose differs from local sample");J r=packet_base(o,id,c.patches.at(id),true,pose.position_m,pose.proper_velocity_m_s,e.binding.begin_s);r["sampled_temperature_K"]=proposal.at("sampled_temperature_K");D count;for(auto carrier:c.arena->rate_carriers(id)){count=count+D(carrier.weight);r["carriers"].push_back({{"native_id",carrier.id},{"weight",carrier.weight},{"kinetic_per_atom_J",m::pic_kinetic_energy_J(carrier)}});}auto n=c.arena->snapshot()->packets.at(id).count;need(s::eq(count,D(n.hi)+D(n.lo)),"actual source native carriers/count");r["exact_atoms"]=count.json();batch["packets"].push_back(r);}
  for(auto&v:a.at("species_sink_receipts")){need(v.at("sink")=="upper_foil"&&v.at("state")=="SS304_CONGRUENT_NEUTRAL"&&v.at("wall_heat_assumed")==false,"foreign native sink");std::string pid=v.at("packet_id");auto x=v.at("position_m").get<m::PicVector>(),u=v.at("proper_velocity_m_s").get<m::PicVector>();J r=packet_base(o,v.at("receipt_id"),c.patches.at(pid),false,x,u,v.at("time_s"));r["packet_id"]=pid;D count;auto pose=c.arena->view(pid);pose.position_m=x;pose.proper_velocity_m_s=u;double K=m::pic_kinetic_energy_J(pose);for(auto&cr:v.at("native_carrier_receipts")){double w=cr.at("weight");need(cr.at("incident_K_J")==K*w,"native sink K currency mismatch");count=count+D(w);r["carriers"].push_back({{"native_id",cr.at("native_id")},{"weight",w},{"kinetic_per_atom_J",K}});}auto limbs=v.at("count");need(s::eq(count,D(limbs[0].get<double>())+D(limbs[1].get<double>()))&&v.at("internal_per_particle_J")==0&&v.at("reference_per_particle_J")==o.reference_per_atom(),"actual native sink count/state");r["exact_atoms"]=count.json();batch["packets"].push_back(r);}
 }
 const J&certified_batch(const s::Binding&b)const override{need(fixture.arena->can_publish(trial)&&batch.at("binding")==s::Owner::describe_binding(b)&&b.gas_trial_sha256==s::hash(trial.audit().dump()),"stale actual native trial");return batch;}
};
struct History:s::GasPort {
 std::map<std::string,J>batches;
 const J&certified_batch(const s::Binding&b)const override{return batches.at(b.gas_trial_sha256);}
 // The native owner has restored and semantically validated the entire v6.2
 // checkpoint first. Bind archived rows to that validated native journal/genesis.
 void verify_native(const m::PicArena&arena,const J&checkpoint,const J&archive){
  std::map<std::string,J>audits;for(auto row:arena.snapshot()->journal){auto a=row.at("payload");a.erase("previous_chain");audits.emplace(s::hash(a.dump()),a);}std::map<std::uint64_t,J>genesis;for(auto&r:checkpoint.at("payload").at("genesis_native"))genesis.emplace(r.at("id"),r);
  for(auto&batch:archive){auto b=batch.at("binding");std::string key=b.at("gas_trial_sha256");need(audits.count(key)&&batch.at("raw_native_audit")==audits.at(key),"material history is absent from actual native journal");const auto&a=audits.at(key);
   for(auto&r:batch.at("packets")){bool emit=r.at("emit");if(emit){for(auto&cr:r.at("carriers")){const auto&g=genesis.at(cr.at("native_id"));m::GapParticle p;p.mass_kg=g.at("m");p.proper_velocity_m_s=g.at("u").get<m::PicVector>();need(g.at("position_m")==r.at("position_m")&&g.at("u")==r.at("proper_velocity_m_s")&&g.at("q")==0&&g.at("weight")==cr.at("weight")&&g.at("m")==r.at("mass_per_atom_kg")&&cr.at("kinetic_per_atom_J")==m::pic_kinetic_energy_J(p),"source history disagrees with actual native genesis fixture");}}
    else {bool found=false;for(auto&v:a.at("species_sink_receipts"))if(v.at("receipt_id")==r.at("receipt_id")){found=true;need(v.at("position_m")==r.at("position_m")&&v.at("proper_velocity_m_s")==r.at("proper_velocity_m_s")&&v.at("time_s")==r.at("time_s")&&v.at("packet_id")==r.at("packet_id")&&v.at("state")==r.at("species")&&v.at("reference_per_particle_J")==r.at("reference_per_atom_J")&&v.at("internal_per_particle_J")==r.at("internal_per_atom_J")&&v.at("native_carrier_receipts").size()==r.at("carriers").size(),"collection history disagrees with actual native first hit");D count;std::size_t i=0;auto u=v.at("proper_velocity_m_s").get<m::PicVector>();m::GapParticle p;p.mass_kg=r.at("mass_per_atom_kg");p.proper_velocity_m_s=u;double K=m::pic_kinetic_energy_J(p);for(auto&cr:r.at("carriers")){auto&nc=v.at("native_carrier_receipts").at(i++);need(cr.at("native_id")==nc.at("native_id")&&cr.at("weight")==nc.at("weight")&&cr.at("kinetic_per_atom_J")==K&&nc.at("incident_K_J")==K*cr.at("weight").get<double>(),"collection native carrier history mismatch");count=count+D(cr.at("weight").get<double>());}need(s::eq(count,D::read(r.at("exact_atoms"))),"collection restart canonical count");}need(found,"missing actual first hit");}
   }
   need(batches.emplace(key,batch).second,"duplicate native history token");
  }
 }
};
J boundary(const s::Owner&o,const m::PicArena&a){return {{"accepted_boundary",true},{"material_prefix",o.prefix()},{"time_s",o.snapshot()->time_s},{"accepted_step",o.snapshot()->accepted_step},{"gas_sha256",a.state_prefix()},{"field_sha256",s::hash("field-fixture-not-Maxwell")},{"source_sha256",s::hash("source-fixture-no-RNG")},{"rng_sha256",s::hash("caller-owned-no-RNG")}};}
