 check(o.can_publish(p)&&native.arena->can_publish(gt),"common local/native preflight");check(native.arena->try_publish(gt),"native first-hit publication");check(o.publish_prevalidated(p),"material no-allocation publication");check(o.rollback(p)&&native.arena->try_rollback(gt)&&o.prefix()==prefix&&native.arena->state_prefix()==nativeprefix&&m::PicArena::fingerprint(native.pic)==finger,"common LIFO native/material rollback restores exact accepted bytes");check(!o.publish_prevalidated(p)&&!o.rollback(p),"rolled-back material token inert");
