 for(int mutation=0;mutation<8;++mutation){auto bad=cp;auto&body=bad["body"];switch(mutation){case 0:body["state"]["cells"][0]["energy_J"]=D(1.).json();break;case 1:body["state"]["cells"][0]["mass_kg"]=D(1.).json();break;case 2:body["state"]["cells"][0]["support_impulse"][0]=D(1.).json();break;case 3:body["state"]["consumed_receipts"]=J::array();break;case 4:body["state"]["journal"][0]["conduction"][0]["fluxes"][0]["energy_J"]=D(1.).json();break;case 5:body["state"]["journal"][0]["binding"]["dt_s"]=2e-9;break;case 6:body["outer_boundary"]["accepted_boundary"]=false;break;case 7:body["state"]["journal"][0]["certified_batch_sha256"]=s::hash("foreign");break;}bad["sha256"]=s::hash(body.dump());s::Owner fresh(config(),temps());auto old=fresh.prefix();reject([&]{fresh.restore(bad,bound,history);},"rehashed semantic restart corruption "+std::to_string(mutation));check(fresh.prefix()==old,"failed restore leaves accepted stock untouched "+std::to_string(mutation));}
